# Refuter: re-run the document_sources and external_citations joins over MY rebuilt field (field_pairs.tsv), via a TEMP table on the read-only connection.
import sqlite3
c=sqlite3.connect('file:/Users/jbotts/frus-analysis/c3/frus-copy-2026-10-25.db?mode=ro',uri=True)
c.execute("create temp table scope(volume_id text, document_id text, primary key(volume_id,document_id))")
c.executemany("insert into scope values(?,?)",[tuple(l.split()) for l in open('field_pairs.tsv') if l.strip()])
n=c.execute("select count(*) from scope").fetchone()[0]; print('scope rows',n)
print('with a document_sources row:',c.execute("select count(*) from scope s join document_sources ds using(volume_id,document_id)").fetchone()[0])
print('record_group values:',c.execute("select ds.record_group, count(*) from scope s join document_sources ds using(volume_id,document_id) group by 1 order by 2 desc").fetchall())
print('citation_era values:',c.execute("select ds.citation_era, count(*) from scope s join document_sources ds using(volume_id,document_id) group by 1 order by 2 desc").fetchall())
r=c.execute("""select count(*), sum(ds.decimal_class is null), min(dd.date_iso), max(dd.date_iso) from scope s join document_sources ds using(volume_id,document_id)
 left join document_dates dd using(volume_id,document_id) where ds.citation_era='decimal' and dd.date_iso>='1910-08'""").fetchone()
print('decimal-era, dated 1910-08 or later: count,no-class,min,max =',r, '| share of %d = %.1f%%  (15/16 = %.1f%%)'%(n,100*r[0]/n,100*15/16))
print('decimal-era regardless of date:',c.execute("select count(*) from scope s join document_sources ds using(volume_id,document_id) where ds.citation_era='decimal'").fetchone())
print('numerical-era rows:',c.execute("select ds.volume_id, count(*) from scope s join document_sources ds using(volume_id,document_id) where ds.citation_era='numerical' group by 1").fetchall())
print('numerical raw:',c.execute("select ds.document_id, ds.raw_text from scope s join document_sources ds using(volume_id,document_id) where ds.citation_era='numerical'").fetchall())
print('lot-file rows:',c.execute("select ds.volume_id,ds.document_id,ds.lot_file,ds.lot_file_norm,ds.raw_text from scope s join document_sources ds using(volume_id,document_id) where ds.lot_file is not null or ds.citation_era='lot'").fetchall())
print('no source row by year:',c.execute("""select substr(dd.date_iso,1,4) y, count(*) from scope s left join document_sources ds using(volume_id,document_id) left join document_dates dd using(volume_id,document_id)
 where ds.volume_id is null group by 1 order by 1""").fetchall())
print('1895-1904 docs: total / without source row:',c.execute("""select count(*), sum(ds.volume_id is null) from scope s left join document_sources ds using(volume_id,document_id) join document_dates dd using(volume_id,document_id) where dd.date_iso<'1905'""").fetchone())
print('country counts (class 8), top 10:',c.execute("""select substr(ds.decimal_class,1,1) cls, substr(ds.decimal_class,2,2) ctry, count(*) from scope s join document_sources ds using(volume_id,document_id)
 where ds.citation_era='decimal' and ds.decimal_class is not null group by 1,2 order by 3 desc limit 10""").fetchall())
print('--- external_citations (pointed-at) ---')
print(c.execute("select count(distinct e.volume_id||'/'||e.document_id), count(*), min(e.volume_id), max(e.volume_id) from scope s join external_citations e using(volume_id,document_id)").fetchone())
print('anchors:',c.execute("select e.anchor,count(*) from scope s join external_citations e using(volume_id,document_id) group by 1").fetchall())
print('earliest dated doc with a citation:',c.execute("select min(dd.date_iso) from scope s join external_citations e using(volume_id,document_id) join document_dates dd on dd.volume_id=s.volume_id and dd.document_id=s.document_id").fetchone())
print('top classes:',c.execute("select e.decimal_class, count(*), count(distinct e.volume_id) from scope s join external_citations e using(volume_id,document_id) group by 1 order by 2 desc limit 8").fetchall())
print('share: %d of %d = %.2f%% ; one in %.1f'%(56,n,100*56/n,n/56))
